/* Keep image uploads small without changing card layout or transparency. */
async function compactCardImages(card){const result=structuredClone(card);for(const key of ['background','logo','stampImage','stampEmptyImage','rewardImage']){const value=result[key];if(typeof value!=='string'||!value.startsWith('data:image/')||value.length<350000)continue;try{const image=new Image();image.src=value;await image.decode();const limit=key==='background'?1600:key==='logo'?800:512,scale=Math.min(1,limit/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL('image/webp',0.92);if(encoded.length<value.length)result[key]=encoded;}catch{/* Preserve the original if browser encoding is unavailable. */}}return result;}
